//go:build cgo

// Package stegano provides idiomatic Go bindings for the stegano steganography
// library via CGO.
//
// # Build requirements
//
// The stegano Rust library must be compiled before using this package:
//
//	cd /path/to/stegano && cargo build --release
//
// Then set linker paths so CGO can find the library:
//
//	export CGO_LDFLAGS="-L$(pwd)/target/release"
//	export DYLD_LIBRARY_PATH="$(pwd)/target/release"   # macOS
//	export LD_LIBRARY_PATH="$(pwd)/target/release"      # Linux
//
// The C declarations come from stegano.h in this directory, generated by
// cbindgen from src/ffi.rs. The header ships with the module, so the package
// builds after a plain `go get github.com/scttfrdmn/stegano/go`; only the
// compiled library has to be supplied through CGO_LDFLAGS.
//
// # Usage
//
//	import stegano "github.com/scttfrdmn/stegano/go"
//
//	// Embed a secret payload into a carrier (format auto-detected).
//	modified, err := stegano.Embed(carrier, []byte("secret"), stegano.WithPassword("key"))
//
//	// Extract it back.
//	payload, err := stegano.Extract(modified, stegano.WithPassword("key"))
//
//	// Work on files directly (streamed for FASTQ, VCF, ... with no size limit).
//	err = stegano.EmbedFile("reads.fastq", "reads.stego.fastq", []byte("secret"))
//	payload, err = stegano.ExtractFile("reads.stego.fastq")
//
//	// Inspect capacity before embedding.
//	info, err := stegano.EstimateCapacity(carrier)
//	fmt.Printf("Format: %s, Total bits: %d\n", info.Format, info.TotalBits)
package stegano

/*
#cgo CFLAGS: -I${SRCDIR}
#cgo LDFLAGS: -lstegano
#cgo darwin LDFLAGS: -framework Security -framework Foundation

#include <stdlib.h>
#include "stegano.h"
*/
import "C"

import (
	"encoding/json"
	"fmt"
	"math"
	"unsafe"
)

// ---------------------------------------------------------------------------
// Format constants
// ---------------------------------------------------------------------------

// Format identifies the carrier data format.
type Format int32

const (
	FormatFASTA         Format = C.CDataFormat_Fasta
	FormatFASTQ         Format = C.CDataFormat_Fastq
	FormatVCF           Format = C.CDataFormat_Vcf
	FormatSAM           Format = C.CDataFormat_Sam
	FormatBAM           Format = C.CDataFormat_Bam
	FormatPNG           Format = C.CDataFormat_Png
	FormatTIFF          Format = C.CDataFormat_Tiff
	FormatMicroscopy    Format = C.CDataFormat_Microscopy
	FormatDICOM         Format = C.CDataFormat_Dicom
	FormatWAV           Format = C.CDataFormat_Wav
	FormatBinarySignal  Format = C.CDataFormat_BinarySignal
	FormatCSVTimeseries Format = C.CDataFormat_CsvTimeseries
	FormatBinary        Format = C.CDataFormat_Binary
	FormatText          Format = C.CDataFormat_Text
	FormatFITS          Format = C.CDataFormat_Fits
)

// String returns a human-readable name for the format.
func (f Format) String() string {
	switch f {
	case FormatFASTA:
		return "FASTA"
	case FormatFASTQ:
		return "FASTQ"
	case FormatVCF:
		return "VCF"
	case FormatSAM:
		return "SAM"
	case FormatBAM:
		return "BAM"
	case FormatPNG:
		return "PNG"
	case FormatTIFF:
		return "TIFF"
	case FormatMicroscopy:
		return "Microscopy"
	case FormatDICOM:
		return "DICOM"
	case FormatWAV:
		return "WAV"
	case FormatBinarySignal:
		return "BinarySignal"
	case FormatCSVTimeseries:
		return "CSVTimeseries"
	case FormatBinary:
		return "Binary"
	case FormatText:
		return "Text"
	case FormatFITS:
		return "FITS"
	default:
		return fmt.Sprintf("Format(%d)", int(f))
	}
}

// strategyKey returns the format_specific JSON key the Rust handler for
// format reads its strategy from, or "" if the format has no strategies.
// Must match strategy_key() in src/carrier.rs.
func strategyKey(format Format) string {
	switch format {
	case FormatPNG, FormatTIFF, FormatMicroscopy:
		return "imagery_strategy"
	case FormatVCF:
		return "vcf_strategy"
	case FormatSAM, FormatBAM:
		return "sam_strategy"
	case FormatDICOM:
		return "dicom_strategy"
	case FormatWAV:
		return "signal_strategy"
	case FormatFASTA, FormatFASTQ:
		return "genomics_strategy"
	case FormatFITS:
		return "fits_strategy"
	default:
		return ""
	}
}

// ---------------------------------------------------------------------------
// Error type
// ---------------------------------------------------------------------------

// ErrorCode is the numeric code returned by FFI operations.
type ErrorCode int

const (
	ErrInvalidParameter     ErrorCode = C.SteganoErrorCode_InvalidParameter
	ErrInsufficientCapacity ErrorCode = C.SteganoErrorCode_InsufficientCapacity
	ErrCryptographic        ErrorCode = C.SteganoErrorCode_CryptographicFailure
	ErrFormatNotSupported   ErrorCode = C.SteganoErrorCode_FormatNotSupported
	ErrDataCorrupted        ErrorCode = C.SteganoErrorCode_DataCorrupted
	ErrGPU                  ErrorCode = C.SteganoErrorCode_GpuError
	ErrIO                   ErrorCode = C.SteganoErrorCode_IoError
	ErrOutputSizeChanged    ErrorCode = C.SteganoErrorCode_OutputSizeChanged
	ErrPanic                ErrorCode = C.SteganoErrorCode_Panic
	ErrUnknown              ErrorCode = C.SteganoErrorCode_Unknown
)

// Error is returned when a stegano FFI operation fails.
type Error struct {
	Code    ErrorCode
	Message string
}

func (e *Error) Error() string {
	return fmt.Sprintf("stegano: %s (code %d)", e.Message, e.Code)
}

// codeToError maps an FFI return code (C `enum SteganoErrorCode`) to an *Error.
func codeToError(code uint32, op string) *Error {
	descriptions := map[ErrorCode]string{
		ErrInvalidParameter:     "invalid parameter",
		ErrInsufficientCapacity: "insufficient carrier capacity for payload",
		ErrCryptographic:        "cryptographic failure",
		ErrFormatNotSupported:   "format not supported",
		ErrDataCorrupted:        "data corrupted or no payload found",
		ErrGPU:                  "GPU error",
		ErrIO:                   "I/O error",
		ErrOutputSizeChanged:    "embedded output size differs from input",
		ErrPanic:                "internal error (panic in stegano library)",
		ErrUnknown:              "unknown error",
	}
	desc, ok := descriptions[ErrorCode(code)]
	if !ok {
		desc = fmt.Sprintf("error code %d", int(code))
	}
	return &Error{Code: ErrorCode(code), Message: fmt.Sprintf("%s: %s", op, desc)}
}

// ---------------------------------------------------------------------------
// Options
// ---------------------------------------------------------------------------

type options struct {
	password string
	format   *Format // nil = auto-detect
	strategy string  // format-specific strategy name (e.g. "auxiliary", "echo")
	cipher   string  // encryption cipher override (e.g. "chacha20")
	stealth  string  // stealth level override
	ecLevel  string  // error-correction level override

	formatSpecific map[string]any // raw format_specific keys (WithFormatSpecific)
}

// Option configures an Embed or Extract call.
type Option func(*options)

// WithPassword sets the encryption password.
// An empty string disables encryption (default).
func WithPassword(password string) Option {
	return func(o *options) { o.password = password }
}

// WithFormat overrides the auto-detected carrier format.
// Use this when the carrier bytes cannot be reliably auto-detected
// (e.g. raw binary data that should be treated as SAM).
func WithFormat(format Format) Option {
	return func(o *options) { o.format = &format }
}

// WithStrategy sets a format-specific embedding/extraction strategy. It is
// sent under the JSON key the handler for the carrier format reads:
//   - PNG/TIFF (imagery_strategy): "lsb", "adaptive", "edge", "dct"
//   - VCF (vcf_strategy):          "info", "quality", "format", "id", "multi"
//   - SAM/BAM (sam_strategy):      "optional", "comment", "quality", "auxiliary", "multi"
//   - DICOM (dicom_strategy):      "private", "metadata", "sequence", "pixel_lsb", "multi"
//   - WAV (signal_strategy):       "timedomain", "frequency", "phase", "spread", "echo"
//   - FASTA/FASTQ (genomics_strategy)
//   - FITS (fits_strategy):        "pixel_lsb", "float_mantissa"
//
// Using WithStrategy with any other format returns ErrInvalidParameter.
// Pass the same strategy to Extract.
func WithStrategy(strategy string) Option {
	return func(o *options) { o.strategy = strategy }
}

// WithCipher selects the encryption cipher ("aes256gcm" or "chacha20").
// Only meaningful when a password is also set via WithPassword; the cipher
// is auto-detected on Extract. Default is "aes256gcm".
func WithCipher(cipher string) Option {
	return func(o *options) { o.cipher = cipher }
}

// WithStealth sets the stealth level: "low", "medium", "high" (default)
// or "maximum".
func WithStealth(level string) Option {
	return func(o *options) { o.stealth = level }
}

// WithECLevel sets the Reed-Solomon error-correction level: "none"
// (default), "low", "medium", "high" or "maximum". Without a password,
// Extract must also be given a non-"none" level if one was used for Embed
// (the actual level is read from the payload).
func WithECLevel(level string) Option {
	return func(o *options) { o.ecLevel = level }
}

// WithFormatSpecific passes an arbitrary format_specific key/value to the
// Rust handler, e.g. WithFormatSpecific("bam_compression", "none") or
// WithFormatSpecific("sam_strategy", "auxiliary"). value must be
// JSON-encodable (string, number, bool, ...). It is merged into the JSON
// options of Embed, Extract, EmbedFile and ExtractFile; the typed options
// (WithStrategy, WithCipher, WithStealth, WithECLevel) take precedence over
// a WithFormatSpecific entry for the same key. Calling it again with the
// same key replaces the earlier value.
func WithFormatSpecific(key string, value any) Option {
	return func(o *options) {
		if o.formatSpecific == nil {
			o.formatSpecific = map[string]any{}
		}
		o.formatSpecific[key] = value
	}
}

func applyOptions(opts []Option) options {
	o := options{}
	for _, opt := range opts {
		opt(&o)
	}
	return o
}

// ---------------------------------------------------------------------------
// CapacityInfo
// ---------------------------------------------------------------------------

// CapacityInfo describes the steganographic capacity of a carrier.
type CapacityInfo struct {
	// TotalBits is the total number of bits available for payload.
	TotalBits int
	// RecommendedBits is a conservative upper bound for reliable embedding.
	RecommendedBits int
	// SteganographicRatio is the fraction of carrier bytes used for embedding.
	SteganographicRatio float64
	// Format is the detected or specified carrier format.
	Format Format
}

// ---------------------------------------------------------------------------
// Initialisation (called once via init())
// ---------------------------------------------------------------------------

func init() {
	// Non-fatal: stegano_init only warms up the shared runtime.
	_ = C.stegano_init()
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

func toUint32(n int, label string) (C.uint32_t, error) {
	if n < 0 {
		return 0, fmt.Errorf("stegano: %s cannot be negative (%d)", label, n)
	}
	if uint64(n) > math.MaxUint32 {
		return 0, fmt.Errorf("stegano: %s (%d) exceeds uint32 max", label, n)
	}
	return C.uint32_t(n), nil
}

func bytesPtr(b []byte) *C.uint8_t {
	return (*C.uint8_t)(unsafe.Pointer(&b[0]))
}

// cString returns a C copy of s (or nil for ""), and a function to free it.
func cString(s string) (*C.char, func()) {
	if s == "" {
		return nil, func() {}
	}
	cs := C.CString(s)
	return cs, func() { C.free(unsafe.Pointer(cs)) }
}

// takeBuffer copies a library-allocated buffer into Go memory and frees it.
func takeBuffer(p *C.uint8_t, n C.uint32_t) []byte {
	if p == nil {
		return nil
	}
	defer C.stegano_free(unsafe.Pointer(p))
	return C.GoBytes(unsafe.Pointer(p), C.int(n))
}

// optionsJSON builds the JSON options object for the v2 FFI functions.
func optionsJSON(o options, format Format) (string, error) {
	m := map[string]any{}
	for k, v := range o.formatSpecific {
		m[k] = v
	}
	if o.strategy != "" {
		key := strategyKey(format)
		if key == "" {
			return "", &Error{
				Code:    ErrInvalidParameter,
				Message: fmt.Sprintf("WithStrategy: format %s has no selectable strategies", format),
			}
		}
		m[key] = o.strategy
	}
	if o.cipher != "" {
		m["cipher"] = o.cipher
	}
	if o.stealth != "" {
		m["stealth"] = o.stealth
	}
	if o.ecLevel != "" {
		m["ec_level"] = o.ecLevel
	}
	if len(m) == 0 {
		return "", nil
	}
	b, err := json.Marshal(m)
	if err != nil {
		return "", &Error{
			Code:    ErrInvalidParameter,
			Message: fmt.Sprintf("options are not JSON-encodable: %v", err),
		}
	}
	return string(b), nil
}

func resolveFormat(carrier []byte, o options) (Format, error) {
	if o.format != nil {
		return *o.format, nil
	}
	return DetectFormat(carrier)
}

// ---------------------------------------------------------------------------
// Public API
// ---------------------------------------------------------------------------

// Version returns the stegano library version string (e.g. "0.5.1").
func Version() string {
	return C.GoString(C.stegano_version())
}

// DetectFormat auto-detects the format of carrier bytes.
// Returns FormatBinary if the format cannot be determined.
func DetectFormat(carrier []byte) (Format, error) {
	if len(carrier) == 0 {
		return FormatBinary, &Error{Code: ErrInvalidParameter, Message: "DetectFormat: carrier is empty"}
	}
	n, err := toUint32(len(carrier), "carrier length")
	if err != nil {
		return FormatBinary, err
	}
	var fmtOut C.uint32_t
	code := C.stegano_detect_format(bytesPtr(carrier), n, &fmtOut)
	if code != C.SteganoErrorCode_Success {
		return FormatBinary, codeToError(code, "DetectFormat")
	}
	return Format(fmtOut), nil
}

// EstimateCapacity returns the embedding capacity of carrier.
// Format is auto-detected unless WithFormat is specified.
func EstimateCapacity(carrier []byte, opts ...Option) (CapacityInfo, error) {
	if len(carrier) == 0 {
		return CapacityInfo{}, &Error{Code: ErrInvalidParameter, Message: "EstimateCapacity: carrier is empty"}
	}
	o := applyOptions(opts)

	format, err := resolveFormat(carrier, o)
	if err != nil {
		return CapacityInfo{}, err
	}
	n, err := toUint32(len(carrier), "carrier length")
	if err != nil {
		return CapacityInfo{}, err
	}

	var capOut C.CCapacityInfo
	code := C.stegano_estimate_capacity(bytesPtr(carrier), n, C.uint32_t(format), &capOut)
	if code != C.SteganoErrorCode_Success {
		return CapacityInfo{}, codeToError(code, "EstimateCapacity")
	}
	return CapacityInfo{
		TotalBits:           int(capOut.total_bits),
		RecommendedBits:     int(capOut.recommended_bits),
		SteganographicRatio: float64(capOut.steganographic_ratio),
		Format:              format,
	}, nil
}

// Embed embeds payload into carrier and returns the embedded carrier bytes.
//
// The returned slice may be longer than carrier: SAM, BAM, VCF and DICOM
// output grows. carrier itself is never modified. Format is auto-detected
// unless WithFormat is specified.
func Embed(carrier, payload []byte, opts ...Option) ([]byte, error) {
	if len(carrier) == 0 {
		return nil, &Error{Code: ErrInvalidParameter, Message: "Embed: carrier is empty"}
	}
	if len(payload) == 0 {
		return nil, &Error{Code: ErrInvalidParameter, Message: "Embed: payload is empty"}
	}
	o := applyOptions(opts)

	format, err := resolveFormat(carrier, o)
	if err != nil {
		return nil, err
	}
	carrierLen, err := toUint32(len(carrier), "carrier length")
	if err != nil {
		return nil, err
	}
	payloadLen, err := toUint32(len(payload), "payload length")
	if err != nil {
		return nil, err
	}
	jsonStr, err := optionsJSON(o, format)
	if err != nil {
		return nil, err
	}

	cPassword, freePassword := cString(o.password)
	defer freePassword()
	cJSON, freeJSON := cString(jsonStr)
	defer freeJSON()

	var outPtr *C.uint8_t
	var outLen C.uint32_t
	code := C.stegano_embed_v2(
		bytesPtr(carrier),
		carrierLen,
		bytesPtr(payload),
		payloadLen,
		C.uint32_t(format),
		cPassword,
		cJSON,
		&outPtr,
		&outLen,
		nil,
	)
	if code != C.SteganoErrorCode_Success {
		return nil, codeToError(code, "Embed")
	}
	return takeBuffer(outPtr, outLen), nil
}

// Extract extracts the embedded payload from carrier.
// Format is auto-detected unless WithFormat is specified.
// The same password (and strategy, if any) used during Embed must be given.
func Extract(carrier []byte, opts ...Option) ([]byte, error) {
	if len(carrier) == 0 {
		return nil, &Error{Code: ErrInvalidParameter, Message: "Extract: carrier is empty"}
	}
	o := applyOptions(opts)

	format, err := resolveFormat(carrier, o)
	if err != nil {
		return nil, err
	}
	carrierLen, err := toUint32(len(carrier), "carrier length")
	if err != nil {
		return nil, err
	}
	jsonStr, err := optionsJSON(o, format)
	if err != nil {
		return nil, err
	}

	cPassword, freePassword := cString(o.password)
	defer freePassword()
	cJSON, freeJSON := cString(jsonStr)
	defer freeJSON()

	var payloadPtr *C.uint8_t
	var payloadLen C.uint32_t
	code := C.stegano_extract_v2(
		bytesPtr(carrier),
		carrierLen,
		C.uint32_t(format),
		cPassword,
		cJSON,
		&payloadPtr,
		&payloadLen,
	)
	if code != C.SteganoErrorCode_Success {
		return nil, codeToError(code, "Extract")
	}
	result := takeBuffer(payloadPtr, payloadLen)
	if len(result) == 0 {
		return nil, &Error{Code: ErrDataCorrupted, Message: "Extract: no payload found"}
	}
	return result, nil
}

// resolveFileFormat returns the WithFormat override or detects the format
// of the file at path (extension, then the first 4 KiB).
func resolveFileFormat(path string, o options, op string) (Format, error) {
	if o.format != nil {
		return *o.format, nil
	}
	cPath := C.CString(path)
	defer C.free(unsafe.Pointer(cPath))
	var fmtOut C.uint32_t
	code := C.stegano_detect_file_format(cPath, &fmtOut)
	if code != C.SteganoErrorCode_Success {
		return FormatBinary, codeToError(code, op)
	}
	return Format(fmtOut), nil
}

// EmbedFile embeds payload into the carrier file inPath and writes the
// result to outPath. There is no size limit on the carrier: streamable
// formats and strategies (FASTQ, VCF info/id/quality, SAM/BAM auxiliary/quality, FITS, WAV timedomain, ...) are streamed
// with constant memory, anything else is read into memory.
//
// outPath is written atomically (temporary file + rename), so on error it
// is left untouched; inPath and outPath may be the same file. Format is
// detected from the file name and its first bytes unless WithFormat is
// specified.
func EmbedFile(inPath, outPath string, payload []byte, opts ...Option) error {
	if inPath == "" || outPath == "" {
		return &Error{Code: ErrInvalidParameter, Message: "EmbedFile: empty path"}
	}
	if len(payload) == 0 {
		return &Error{Code: ErrInvalidParameter, Message: "EmbedFile: payload is empty"}
	}
	o := applyOptions(opts)

	format, err := resolveFileFormat(inPath, o, "EmbedFile")
	if err != nil {
		return err
	}
	jsonStr, err := optionsJSON(o, format)
	if err != nil {
		return err
	}

	cIn := C.CString(inPath)
	defer C.free(unsafe.Pointer(cIn))
	cOut := C.CString(outPath)
	defer C.free(unsafe.Pointer(cOut))
	cPassword, freePassword := cString(o.password)
	defer freePassword()
	cJSON, freeJSON := cString(jsonStr)
	defer freeJSON()

	code := C.stegano_embed_file(
		cIn,
		cOut,
		bytesPtr(payload),
		C.size_t(len(payload)),
		C.uint32_t(format),
		cPassword,
		cJSON,
		nil,
	)
	if code != C.SteganoErrorCode_Success {
		return codeToError(code, "EmbedFile")
	}
	return nil
}

// ExtractFile extracts the embedded payload from the carrier file at path.
// Streamable formats are streamed and reading stops as soon as the payload
// is complete; anything else is read into memory. Format is detected from
// the file name and its first bytes unless WithFormat is specified.
func ExtractFile(path string, opts ...Option) ([]byte, error) {
	if path == "" {
		return nil, &Error{Code: ErrInvalidParameter, Message: "ExtractFile: empty path"}
	}
	o := applyOptions(opts)

	format, err := resolveFileFormat(path, o, "ExtractFile")
	if err != nil {
		return nil, err
	}
	jsonStr, err := optionsJSON(o, format)
	if err != nil {
		return nil, err
	}

	cPath := C.CString(path)
	defer C.free(unsafe.Pointer(cPath))
	cPassword, freePassword := cString(o.password)
	defer freePassword()
	cJSON, freeJSON := cString(jsonStr)
	defer freeJSON()

	var payloadPtr *C.uint8_t
	var payloadLen C.size_t
	code := C.stegano_extract_file(
		cPath,
		C.uint32_t(format),
		cPassword,
		cJSON,
		&payloadPtr,
		&payloadLen,
	)
	if code != C.SteganoErrorCode_Success {
		return nil, codeToError(code, "ExtractFile")
	}
	if payloadPtr == nil {
		return nil, &Error{Code: ErrDataCorrupted, Message: "ExtractFile: no payload found"}
	}
	defer C.stegano_free(unsafe.Pointer(payloadPtr))
	if uint64(payloadLen) > math.MaxInt32 {
		return nil, &Error{Code: ErrInvalidParameter, Message: "ExtractFile: payload too large"}
	}
	result := C.GoBytes(unsafe.Pointer(payloadPtr), C.int(payloadLen))
	if len(result) == 0 {
		return nil, &Error{Code: ErrDataCorrupted, Message: "ExtractFile: no payload found"}
	}
	return result, nil
}
